import{_ as l,l as r,o as e,c as i,v as o,p as c,x as t,d,i as A,S as n}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"ABI 与代码生成","description":"","frontmatter":{"title":"ABI 与代码生成","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/abi-codegen.md","filePath":"cs/abi-codegen.md","lastUpdated":1789023840000}'),p={name:"cs/abi-codegen.md"};function I(B,a,h,_,E,S){const s=r("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="abi-与代码生成" tabindex="-1">ABI 与代码生成 <a class="header-anchor" href="#abi-与代码生成" aria-label="Permalink to &quot;ABI 与代码生成&quot;">​</a></h1><div class="epigraph"><p>应用程序二进制接口规定寄存器谁保存、参数怎么传、栈帧怎么长；代码生成必须按同一份文档发指令，函数才能跨编译单元互调。</p><footer>—— 据 System V Application Binary Interface, AMD64 Architecture Processor Supplement；RISC-V ELF psABI 整理</footer></div><p>上一课<a href="/cs/peephole">窥孔与窥视窗</a>清理了函数体内的短序列。<a href="/cs/peephole">调用约定与栈</a>在组成课已讲帧与返回地址；<a href="/cs/riscv-int-isa">RISC-V 整数指令</a>已给出 <code>jal</code>/<code>jalr</code> 与整数寄存器名。本课不重画五级流水线。缺口是：把那些硬件事实<strong>写成跨编译器的合同</strong>——哪几个是参数寄存器、哪几个 callee-save、栈对齐、谁清参数区——并在序言/尾声里真正发射。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>着色已选物理寄存器，但「<code>x10</code> 是第一个整数参数」不是 ISA 强制，是 ABI。两个目标文件若一个把返回值放 <code>x10</code>、一个去栈上找，链接起来仍崩。缺口是代码生成器遵守一份 ABI 文本：System V AMD64 或 RISC-V psABI，而不是发明第四种约定。</p><p>序言：保存返回地址与 callee-save、调整 <code>sp</code>、对齐。尾声：恢复、返回。可变参数、结构体返回按文档走间接。本课不重讲异常入口。</p><h3 id="abi-不是-isa-子集" tabindex="-1">ABI 不是 ISA 子集 <a class="header-anchor" href="#abi-不是-isa-子集" aria-label="Permalink to &quot;ABI 不是 ISA 子集&quot;">​</a></h3><p>ISA 说指令编码；ABI 说软件约定。无 ABI 的「合法机器码」仍无法与 libc 互调。组成课的调用约定课给了栈直觉；本课把寄存器号与对齐钉到可汇编。</p><p><span class="marginnote">System V AMD64 ABI 与 RISC-V ELF psABI 是平台文档。本课引用它们的规则层级，不抄整张寄存器表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按目标选 ABI。参数：前几个进规定寄存器，其余入栈。生成 call：把实参挪到合同位置，<code>jal</code>/<code>call</code>。被调者按合同保存。栈槽给溢出与局部，对齐 16 字节等条款写进帧布局。</p>',11)),(e(),c(n,null,{default:t(()=>[A(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IRCALL%5B%22IR%20call%22%5D%20--%3E%20ABI%5B%22psABI%20%2F%20SysV%20%E5%90%88%E5%90%8C%22%5D%0A%20%20ABI%20--%3E%20ARG%5B%22%E5%8F%82%E6%95%B0%E5%AF%84%E5%AD%98%E5%99%A8%E6%88%96%E6%A0%88%22%5D%0A%20%20ABI%20--%3E%20PRO%5B%22%E5%BA%8F%E8%A8%80%20%2F%20%E5%B0%BE%E5%A3%B0%22%5D%0A%20%20PRO%20--%3E%20OBJ%5B%22%E5%8F%AF%E9%87%8D%E5%AE%9A%E4%BD%8D%E6%8C%87%E4%BB%A4%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>窥孔不得破坏合同处的 <code>sp</code> 与保存集。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>同一 ISA、不同 OS 可以不同 ABI（Windows x64 对 System V）。交叉编译必须选对三元组。叶子函数可简化序言，仍须对齐与红区规则（若文档有红区）。本课点名，不把红区当所有目标的默认。</p><p>与特权级、系统调用号：那是另一份 ABI（syscall ABI），后课操作系统再接；本课是用户态函数调用。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不解析 ELF 重定位项、不加载共享库。不实现完整 libc 启动（<code>_start</code>、<code>argc</code>）。后课默认：每个函数的入口出口遵守目标 ABI。链接把符号引用变成地址。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>代码生成按 ABI 放参数、保存寄存器、对齐栈。</li><li>先修：调用约定课 + RISC-V 整数 ISA；合同文本是 SysV/psABI。</li><li>ISA 合法不等于能与其他目标文件互调。</li><li>出处：System V AMD64 ABI；RISC-V ELF psABI；Aho et al., 龙书第 7–8 章。</li></ul>',8))])}const b=l(p,[["render",I]]);export{u as __pageData,b as default};
